"""Separate review copy only. Never edits shared Showcase."""
from pathlib import Path
import sys,shutil
root=Path(__file__).resolve().parents[1];out=Path(sys.argv[1]).resolve();assets=Path(sys.argv[2]).resolve();out.mkdir(parents=True,exist_ok=True)
assert root not in out.parents or 'artifacts'in out.parts
for name in ['graphics','vendor']:shutil.copytree(root/name,out/name,dirs_exist_ok=True)
shutil.copytree(assets,out/'graphics/models/p31r',dirs_exist_ok=True);shutil.copy2(root/'research/bum07-p31/assets/bum07-p31-experimental.glb',out/'graphics/models/p31.glb')
s=(root/'graphics/showcase.js').read_text().replace(' updateFollowing();controls.update();',' if(!window.__repairViewLock)updateFollowing();controls.update();').replace("id.startsWith('bum')?1.9:2.2",'2.2').replace("state.version==='bum07'?record.height*.10:0","['bum07','local'].includes(state.version)?record.height*.10:0")
api="""  lockRepairView(v){window.__repairViewLock=true;controls.enableDamping=false;turntable.rotation.y=v.angle;controls.target.fromArray(v.target);camera.position.fromArray(v.camera);controls.update();needsRender=true;},
  repairExpression(mode,value){active.model.traverse(o=>{if(!o.morphTargetDictionary)return;const d=o.morphTargetDictionary,w=o.morphTargetInfluences;for(const[n,i]of Object.entries(d))if(n.startsWith('FH_'))w[i]=0;if(mode==='Smile'&&d.FH_Smile!==undefined)w[d.FH_Smile]=value;if(mode==='Blink'){if(d.FH_Blink25!==undefined){const names=['Basis','FH_Blink25','FH_Blink50','FH_Blink75','FH_Blink'],pos=Math.min(4,value*4),lo=Math.min(3,Math.floor(pos)),t=pos-lo;if(lo>0)w[d[names[lo]]]=1-t;w[d[names[lo+1]]]=t;}else if(d.FH_Blink!==undefined)w[d.FH_Blink]=value;}});needsRender=true;},
  repairEyeID(){const saved=[];const green=new THREE.MeshBasicMaterial({color:0x00ff00,toneMapped:false}),red=new THREE.MeshBasicMaterial({color:0xff0000,toneMapped:false});let heads=0,eyes=0;scene.traverse(o=>{if(!o.isMesh)return;saved.push([o,o.material,o.visible]);const n=o.name.toLowerCase().replaceAll('_',' ');if(/unified head|reconstructed head|thick orbital lid/.test(n)){o.visible=true;o.material=green;heads++;}else if(/globe|iris|pupil|catchlight/.test(n)&&active.model.getObjectById(o.id)){o.visible=true;o.material=red;eyes++;}else o.visible=false;});try{renderer.render(scene,camera);const c=document.createElement('canvas');c.width=renderer.domElement.width;c.height=renderer.domElement.height;const x=c.getContext('2d');x.drawImage(renderer.domElement,0,0);const data=x.getImageData(0,0,c.width,c.height).data;let redPixels=0,greenPixels=0;for(let i=0;i<data.length;i+=4){if(data[i]>180&&data[i+1]<45&&data[i+2]<45)redPixels++;if(data[i+1]>180&&data[i]<45&&data[i+2]<45)greenPixels++;}return{redPixels,greenPixels,heads,eyes,png:c.toDataURL('image/png').split(',')[1]};}finally{for(const[o,m,v]of saved){o.material=m;o.visible=v;}green.dispose();red.dispose();renderer.render(scene,camera);needsRender=true;}},
"""
assert '  getMetrics:reportBase,'in s;s=s.replace('  getMetrics:reportBase,',api+'  getMetrics:reportBase,');(out/'graphics/showcase.js').write_text(s);print('P31R_ISOLATED_REVIEW',out)
